mapper.select:
select enroll_id, course_id, student_id, enroll_source, enroll_status, progress_percent,
       last_study_time, finish_time, create_by, create_time, update_by, update_time, remark
from edu_course_enroll
where course_id = #{courseId}
  and student_id = #{studentId}
limit 1

